/**
 * One-off converter: docs/spec/AI_Advent_Calendar_Gift_Idea_Bank.md → gift-library/ideas/<id>.md (GIFT_WORKSHOP.md §4, D2, D3).
 *
 * Title, group and summary come verbatim from the bank. The fields the bank does not give are filled from the
 * ENRICHMENT table below; the bank's conditional rules ("developer-context only", "only if pet context exists", …)
 * land in suitable_if / avoid_if. Re-running overwrites the files, so edit ENRICHMENT rather than the generated files
 * if you want the change to survive a re-run (or stop running the converter once the library is curated by hand).
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { kebab, parseBank, type BankIdea } from '../src/library/bank.js';
import { stringifyFrontmatter } from '../src/library/frontmatter.js';
import { IdeaFrontmatterSchema, type IdeaFrontmatter, type SkillName } from '../src/shared/idea.js';

type Effort = IdeaFrontmatter['effort'];
type RealWorld = IdeaFrontmatter['real_world'];

interface Enrichment {
  suitable_if: string;
  avoid_if: string;
  forms: string[];
  minimum_done: string;
  hooks: string[];
  skills: SkillName[];
  effort: Effort;
  /** Defaults to "suggest" for groups G and H, "none" otherwise. */
  real_world?: RealWorld;
  checks: string[];
  variations: string[];
  /** Body: creative notes with one Great:, one Lazy: and a Pitfall: line. */
  notes: string[];
}

/** Titles whose id is not the plain article-stripped kebab (see idFor). */
const ID_OVERRIDES: Record<string, string> = {
  'A Night somewhere': 'a-night-somewhere', // "night-somewhere" reads oddly; keep the article
  "Your Startup's Obituary": 'startup-obituary', // "startups-obituary" loses the possessive meaning
};

export function idFor(title: string, taken: Set<string>): string {
  const override = ID_OVERRIDES[title];
  if (override) return override;
  const full = kebab(title);
  const stripped = full.replace(/^(the|your|a)-/, '');
  const candidate = stripped.length >= 8 && stripped.includes('-') ? stripped : full;
  return taken.has(candidate) ? full : candidate;
}

