const COMMENTS = {
  group: 'A–H as in the bank',
  effort: 'low | medium | high (token band hint only)',
  real_world: 'none | suggest (agent never purchases)',
  status: 'candidate | approved',
};

export function convertIdea(idea: BankIdea, id: string): string {
  const e = ENRICHMENT[id];
  if (!e) throw new Error(`no enrichment for "${idea.title}" (id ${id}); add it to ENRICHMENT in scripts/library-convert.ts`);
  const realWorld: RealWorld = e.real_world ?? (idea.group === 'G' || idea.group === 'H' ? 'suggest' : 'none');
  const frontmatter: IdeaFrontmatter = {
    id,
    title: idea.title,
    group: idea.group,
    summary: idea.description,
    suitable_if: e.suitable_if,
    avoid_if: e.avoid_if,
    forms: e.forms,
    minimum_done: e.minimum_done,
    personalization_hooks: e.hooks,
    skills: e.skills,
    effort: e.effort,
    real_world: realWorld,
    quality_checks: e.checks,
    variations: e.variations,
    status: 'candidate',
  };
  const checked = IdeaFrontmatterSchema.parse(frontmatter);
  return stringifyFrontmatter(checked, e.notes.join('\n'), { blockListKeys: ['variations'], comments: COMMENTS });
}

export function convertBank(markdown: string): Array<{ id: string; title: string; group: string; text: string }> {
  const ideas = parseBank(markdown);
  const taken = new Set<string>();
  return ideas.map((idea) => {
    const id = idFor(idea.title, taken);
    if (taken.has(id)) throw new Error(`duplicate id "${id}" for "${idea.title}"`);
    taken.add(id);
    return { id, title: idea.title, group: idea.group, text: convertIdea(idea, id) };
  });
}

const isMain = process.argv[1] !== undefined && import.meta.url === pathToFileURL(resolve(process.argv[1])).href;
if (isMain) {
  const source = resolve(process.cwd(), 'docs/spec/AI_Advent_Calendar_Gift_Idea_Bank.md');
  const outDir = resolve(process.cwd(), 'gift-library/ideas');
  mkdirSync(outDir, { recursive: true });
  const converted = convertBank(readFileSync(source, 'utf8'));
  for (const c of converted) writeFileSync(resolve(outDir, `${c.id}.md`), c.text);
  const unused = Object.keys(ENRICHMENT).filter((k) => !converted.some((c) => c.id === k));
  if (unused.length > 0) console.warn(`library-convert: enrichment entries without a bank idea: ${unused.join(', ')}`);
  console.log(`library-convert: wrote ${converted.length} ideas to gift-library/ideas/. Now run: npm run library:index`);
}
